package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate1Test {

  @Test
  void newDirectoryStream_rootDedupesFiltersAndRejectsMissingDirectories() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-mutagate-", ".tar");
    try {
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        addFile(tarOut, "a.txt", "a");
        addFile(tarOut, "dir/x.txt", "x");
        addFile(tarOut, "dir/sub/y.txt", "y");
        addFile(tarOut, "dir/sub/z.txt", "z");
        addFile(tarOut, "other/q.txt", "q");
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        // Root listing: unique first segments, in archive order.
        assertEquals(List.of("a.txt", "dir", "other"), names(fs.getPath("/"), null));

        // Nested directory: "sub" appears once even though two entries live under it.
        assertEquals(List.of("x.txt", "sub"), names(fs.getPath("/dir"), null));

        // Deeper directory lists only its immediate children.
        assertEquals(List.of("y.txt", "z.txt"), names(fs.getPath("/dir/sub"), null));

        // Filter is applied to the children.
        assertEquals(
            List.of("x.txt"),
            names(fs.getPath("/dir"), p -> p.getFileName().toString().endsWith(".txt")));
        assertEquals(List.of(), names(fs.getPath("/dir"), p -> false));

        // Missing directory and a regular file both have no children -> NoSuchFileException.
        assertThrows(NoSuchFileException.class, () -> Files.newDirectoryStream(fs.getPath("/nope")));
        assertThrows(NoSuchFileException.class, () -> Files.newDirectoryStream(fs.getPath("/a.txt")));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }

  private static List<String> names(Path dir, DirectoryStream.Filter<Path> filter) throws IOException {
    List<String> result = new ArrayList<>();
    try (DirectoryStream<Path> ds =
        filter == null ? Files.newDirectoryStream(dir) : Files.newDirectoryStream(dir, filter)) {
      for (Path p : ds) {
        result.add(p.getFileName().toString());
      }
    }
    return result;
  }

  private static void addFile(TarArchiveOutputStream tarOut, String name, String content) throws IOException {
    byte[] data = content.getBytes(StandardCharsets.UTF_8);
    TarArchiveEntry entry = new TarArchiveEntry(name);
    entry.setSize(data.length);
    tarOut.putArchiveEntry(entry);
    tarOut.write(data);
    tarOut.closeArchiveEntry();
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.FileSystemNotFoundException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate2Test {
  @Test
  void getPath_validationAndEntryPartHandling() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-test-", ".tar");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry entry = new TarArchiveEntry("hello.txt");
        entry.setSize(data.length);
        tarOut.putArchiveEntry(entry);
        tarOut.write(data);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      String archive = tarPath.toAbsolutePath().toString();

      // Validation failures
      assertThrows(NullPointerException.class, () -> provider.getPath(null));
      assertThrows(IllegalArgumentException.class, () -> provider.getPath(URI.create("file:///tmp/x.tar")));
      assertThrows(IllegalArgumentException.class, () -> provider.getPath(URI.create("tar:opaque")));

      // Not registered yet
      assertThrows(
          FileSystemNotFoundException.class, () -> provider.getPath(URI.create("tar:" + archive)));
      assertThrows(
          FileSystemNotFoundException.class,
          () -> provider.getPath(URI.create("tar:" + archive + "!/hello.txt")));

      try (FileSystem fs = provider.newFileSystem(tarPath, Map.of())) {
        // No bang: archive root, absolute, in the registered file system
        TarPath root = (TarPath) provider.getPath(URI.create("tar:" + archive));
        assertEquals("", root.entryName());
        assertTrue(root.isAbsolute());
        assertSame(fs, root.getFileSystem());

        // Bang with only a slash: root entry
        TarPath bangRoot = (TarPath) provider.getPath(URI.create("tar:" + archive + "!/"));
        assertEquals("", bangRoot.entryName());
        assertSame(fs, bangRoot.getFileSystem());

        // Multiple leading slashes are all stripped
        TarPath multi = (TarPath) provider.getPath(URI.create("tar:" + archive + "!///hello.txt"));
        assertEquals("hello.txt", multi.entryName());
        assertTrue(multi.isAbsolute());
        assertSame(fs, multi.getFileSystem());

        // No leading slash after bang
        TarPath noSlash = (TarPath) provider.getPath(URI.create("tar:" + archive + "!hello.txt"));
        assertEquals("hello.txt", noSlash.entryName());

        // Unknown archive still not found while another is registered
        assertThrows(
            FileSystemNotFoundException.class,
            () -> provider.getPath(URI.create("tar:" + archive + ".other!/hello.txt")));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.OpenOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Map;
import java.util.Set;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate3Test {
  @Test
  void newByteChannel_optionHandling_sizeAndSeek() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-test-", ".tar");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry entry = new TarArchiveEntry("hello.txt");
        entry.setSize(data.length);
        tarOut.putArchiveEntry(entry);
        tarOut.write(data);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path p = fs.getPath("/hello.txt");

        // null options and empty options are treated as read
        try (SeekableByteChannel ch = provider.newByteChannel(p, null)) {
          assertEquals(5L, ch.size());
          assertEquals(0L, ch.position());
        }
        try (SeekableByteChannel ch = provider.newByteChannel(p, Set.<OpenOption>of())) {
          assertEquals(5L, ch.size());
        }

        // READ: read, check position, then seek and re-read
        try (SeekableByteChannel ch = provider.newByteChannel(p, Set.of(StandardOpenOption.READ))) {
          assertTrue(ch.isOpen());
          ByteBuffer buf = ByteBuffer.allocate(16);
          int n = ch.read(buf);
          assertEquals(5, n);
          assertEquals(5L, ch.position());
          buf.flip();
          assertEquals("hello", StandardCharsets.UTF_8.decode(buf).toString());

          ch.position(1);
          ByteBuffer buf2 = ByteBuffer.allocate(16);
          assertEquals(4, ch.read(buf2));
          buf2.flip();
          assertEquals("ello", StandardCharsets.UTF_8.decode(buf2).toString());
        }

        // write-ish options are rejected, even combined with READ
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p, Set.of(StandardOpenOption.WRITE)));
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p, Set.of(StandardOpenOption.READ, StandardOpenOption.WRITE)));
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p, Set.of(StandardOpenOption.READ, StandardOpenOption.APPEND)));
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p,
                Set.of(StandardOpenOption.READ, StandardOpenOption.TRUNCATE_EXISTING)));
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p, Set.of(StandardOpenOption.READ, StandardOpenOption.CREATE)));
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p, Set.of(StandardOpenOption.READ, StandardOpenOption.CREATE_NEW)));

        // non-read option without READ is rejected
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(p, Set.of(StandardOpenOption.SYNC)));

        // missing entry
        Path missing = fs.getPath("/missing.txt");
        assertThrows(NoSuchFileException.class,
            () -> provider.newByteChannel(missing, Set.of(StandardOpenOption.READ)));

        // foreign path type
        Path foreign = Path.of("hello.txt");
        assertThrows(UnsupportedOperationException.class,
            () -> provider.newByteChannel(foreign, Set.of(StandardOpenOption.READ)));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.Map;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate4Test {
  @Test
  void readAttributesString_viewParsingAndErrors() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-mutagate4-", ".tar");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry entry = new TarArchiveEntry("hello.txt");
        entry.setSize(data.length);
        tarOut.putArchiveEntry(entry);
        tarOut.write(data);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path p = fs.getPath("/hello.txt");
        Path missing = fs.getPath("/missing.txt");

        // View name without colon defaults to all attributes.
        Map<String, Object> noColon = provider.readAttributes(p, "basic");
        Map<String, Object> star = provider.readAttributes(p, "basic:*");
        assertEquals(star.keySet(), noColon.keySet());
        assertEquals(5L, (Long) noColon.get("size"));
        assertEquals(Boolean.TRUE, noColon.get("isRegularFile"));
        assertEquals(Boolean.FALSE, noColon.get("isDirectory"));

        // Null attributes string.
        assertThrows(NullPointerException.class, () -> provider.readAttributes(p, (String) null));

        // Unsupported views.
        UnsupportedOperationException e1 =
            assertThrows(UnsupportedOperationException.class, () -> provider.readAttributes(p, "posix:*"));
        assertTrue(e1.getMessage().contains("posix"));
        assertThrows(UnsupportedOperationException.class, () -> provider.readAttributes(p, "posix"));
        assertThrows(UnsupportedOperationException.class, () -> provider.readAttributes(p, "Basic:size"));

        // View validation happens before the entry is looked up.
        assertThrows(
            UnsupportedOperationException.class, () -> provider.readAttributes(missing, "posix:*"));

        // Missing entry with a valid view.
        assertThrows(NoSuchFileException.class, () -> provider.readAttributes(missing, "basic:*"));
        assertThrows(NoSuchFileException.class, () -> provider.readAttributes(missing, "basic"));

        // Non-tar path.
        assertThrows(
            UnsupportedOperationException.class,
            () -> provider.readAttributes(Path.of("x"), "basic:*"));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate5Test {
  @Test
  void pathExistsInTar_coversNullEmptyExactImpliedAndNonMatches() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-mutagate5-", ".tar");
    try {
      byte[] data = "x".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        for (String name : new String[] {"root.txt", "dir/sub/leaf.txt", "./dot/b.txt"}) {
          TarArchiveEntry e = new TarArchiveEntry(name);
          e.setSize(data.length);
          tarOut.putArchiveEntry(e);
          tarOut.write(data);
          tarOut.closeArchiveEntry();
        }
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      try (FileSystem fs = provider.newFileSystem(tarPath, Map.of())) {
        TarFileSystem tfs = (TarFileSystem) fs;

        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, null));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, ""));

        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "root.txt"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dir/sub/leaf.txt"));

        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dir"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dir/sub"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dot"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dot/b.txt"));

        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "di"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "dir/su"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "dir/sub/leaf"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "root.txt/child"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "missing"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "sub"));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.AccessDeniedException;
import java.nio.file.AccessMode;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate6Test {
  @Test
  void checkAccess_modesAndExistenceCombinations() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-test-", ".tar");
    try {
      byte[] data = "inner".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry entry = new TarArchiveEntry("dir/inner.txt");
        entry.setSize(data.length);
        tarOut.putArchiveEntry(entry);
        tarOut.write(data);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path file = fs.getPath("/dir/inner.txt");
        Path impliedDir = fs.getPath("/dir");
        Path root = fs.getPath("/");
        Path missing = fs.getPath("/dir/missing.txt");

        // No modes: existing paths succeed.
        assertDoesNotThrow(() -> provider.checkAccess(file));
        assertDoesNotThrow(() -> provider.checkAccess(impliedDir));
        assertDoesNotThrow(() -> provider.checkAccess(root));

        // Null modes array behaves like no modes.
        assertDoesNotThrow(() -> provider.checkAccess(file, (AccessMode[]) null));

        // READ succeeds on files, implied directories and root.
        assertDoesNotThrow(() -> provider.checkAccess(file, AccessMode.READ));
        assertDoesNotThrow(() -> provider.checkAccess(impliedDir, AccessMode.READ));
        assertDoesNotThrow(() -> provider.checkAccess(root, AccessMode.READ));

        // Any non-READ mode is denied, even when combined with READ.
        assertThrows(AccessDeniedException.class,
            () -> provider.checkAccess(file, AccessMode.EXECUTE));
        assertThrows(AccessDeniedException.class,
            () -> provider.checkAccess(file, AccessMode.READ, AccessMode.WRITE));
        assertThrows(AccessDeniedException.class,
            () -> provider.checkAccess(impliedDir, AccessMode.WRITE));
        assertThrows(AccessDeniedException.class,
            () -> provider.checkAccess(root, AccessMode.EXECUTE));

        // Missing paths fail with NoSuchFileException regardless of modes.
        assertThrows(NoSuchFileException.class, () -> provider.checkAccess(missing));
        assertThrows(NoSuchFileException.class,
            () -> provider.checkAccess(missing, AccessMode.EXECUTE));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.nio.file.attribute.PosixFileAttributes;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate7Test {
  @Test
  void readAttributes_typedVariant_handlesTypesPathsAndMissingEntries() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-mutagate7-", ".tar");
    try {
      byte[] innerData = "inner".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry inner = new TarArchiveEntry("dir/sub/inner.txt");
        inner.setSize(innerData.length);
        tarOut.putArchiveEntry(inner);
        tarOut.write(innerData);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path file = fs.getPath("/dir/sub/inner.txt");

        BasicFileAttributes fileAttrs = provider.readAttributes(file, BasicFileAttributes.class);
        assertTrue(fileAttrs.isRegularFile());
        assertFalse(fileAttrs.isDirectory());
        assertFalse(fileAttrs.isSymbolicLink());
        assertFalse(fileAttrs.isOther());
        assertEquals(innerData.length, fileAttrs.size());

        BasicFileAttributes dirAttrs = provider.readAttributes(fs.getPath("/dir/sub"), BasicFileAttributes.class);
        assertTrue(dirAttrs.isDirectory());
        assertFalse(dirAttrs.isRegularFile());
        assertFalse(dirAttrs.isSymbolicLink());

        // Unsupported attribute type is rejected.
        assertThrows(
            UnsupportedOperationException.class,
            () -> provider.readAttributes(file, PosixFileAttributes.class));

        // Missing entry is reported as NoSuchFileException.
        assertThrows(
            NoSuchFileException.class,
            () -> provider.readAttributes(fs.getPath("/dir/missing.txt"), BasicFileAttributes.class));

        // Non-TarPath is rejected.
        Path foreign = Path.of("some-file.txt");
        assertThrows(
            UnsupportedOperationException.class,
            () -> provider.readAttributes(foreign, BasicFileAttributes.class));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate8Test {
  @Test
  void readTarBasicAttributes_nestedEntries_sizesTypesAndMissingPaths() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-test-", ".tar");
    try {
      byte[] innerData = "inner".getBytes(StandardCharsets.UTF_8);
      byte[] leafData = "leaf".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry inner = new TarArchiveEntry("dir/inner.txt");
        inner.setSize(innerData.length);
        tarOut.putArchiveEntry(inner);
        tarOut.write(innerData);
        tarOut.closeArchiveEntry();

        TarArchiveEntry leaf = new TarArchiveEntry("dir/sub/leaf.txt");
        leaf.setSize(leafData.length);
        tarOut.putArchiveEntry(leaf);
        tarOut.write(leafData);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        TarPath innerPath = (TarPath) fs.getPath("/dir/inner.txt");
        BasicFileAttributes innerAttrs = TarFileSystemProvider.readTarBasicAttributes(innerPath);
        assertTrue(innerAttrs.isRegularFile());
        assertFalse(innerAttrs.isDirectory());
        assertFalse(innerAttrs.isSymbolicLink());
        assertFalse(innerAttrs.isOther());
        assertEquals(innerData.length, innerAttrs.size());

        TarPath leafPath = (TarPath) fs.getPath("/dir/sub/leaf.txt");
        BasicFileAttributes leafAttrs = TarFileSystemProvider.readTarBasicAttributes(leafPath);
        assertTrue(leafAttrs.isRegularFile());
        assertEquals(leafData.length, leafAttrs.size());

        TarPath subPath = (TarPath) fs.getPath("/dir/sub");
        BasicFileAttributes subAttrs = TarFileSystemProvider.readTarBasicAttributes(subPath);
        assertTrue(subAttrs.isDirectory());
        assertFalse(subAttrs.isRegularFile());
        assertFalse(subAttrs.isSymbolicLink());

        // Partial segment name is not a prefix directory.
        TarPath partial = (TarPath) fs.getPath("/dir/inn");
        assertThrows(NoSuchFileException.class, () -> TarFileSystemProvider.readTarBasicAttributes(partial));

        TarPath missingChild = (TarPath) fs.getPath("/dir/sub/missing.txt");
